function families(){return head('家庭列表','按家庭管理成员、设备和记录的访问范围。',btn('创建家庭','create-family','primary','plus'))+'<div class="toolbar"><div class="search">'+I('search')+'<input id="table-filter" aria-label="搜索家庭" placeholder="搜索家庭名称或管理员"></div><select aria-label="家庭状态" data-filter-table><option>全部状态</option><option>正常</option><option>待绑定</option></select><span class="spacer"></span><span class="muted small">2 个家庭 · 示例数据</span></div><section class="panel flush">'+table(['家庭','管理员','成员','设备','记录访问','操作'],['<tr data-filter-row data-family="林的家"><td>'+person('林的家','创建于 2026.11.01','teal')+'</td><td>林女士</td><td>3 人</td><td>2 台</td><td>'+B('授权成员可见','green')+'</td><td>'+L('查看家庭','#/family','flat','chevron')+'</td></tr>','<tr data-filter-row data-family="周的家"><td>'+person('周的家','创建于 2026.11.05','blue')+'</td><td>周先生</td><td>2 人</td><td>1 台</td><td>'+B('管理员可见')+'</td><td>'+L('查看家庭','#/family','flat','chevron')+'</td></tr>'])+foot(2)+'</section>';} 
