function tasks(){return head('任务中心','查看任务执行、结果来源与失败原因。',btn('查看接入路线','eino-plan','','tasks'))+N('Eino 尚未接入。归档摘要与历史查询为建议的首个接入闭环，以下为拟议流程预览。','info')+'<div class="grid-main mt">'+panel('首个任务闭环','<div class="timeline"><div class="timeline-item"><h3>聊天结束，记录已经保存</h3><p class="muted">服务端按明确结束或30分钟空闲规则分段。</p></div><div class="timeline-item"><h3>后台生成摘要</h3><p class="muted">读取有权限的正文与播放证据，生成带来源的摘要。</p></div><div class="timeline-item"><h3>保存并更新索引</h3><p class="muted">同一任务版本只提交一次结果，失败可有界重试。</p></div><div class="timeline-item"><h3>新聊天按需查询</h3><p class="muted">检索旧内容，把有来源的结果交回实时语音回答。</p></div></div>',B('拟接入'))+panel('各层负责什么',D([['语音与实际停播','现有Go实时核心'],['30分钟会话边界','业务会话服务'],['摘要和查询编排','Eino任务模块（待接入）'],['身份与访问范围','家庭/设备授权服务'],['归档正文与删除','业务存储'],['执行进度','任务记录与检查点']]))+'</div><section class="panel flush mt">'+table(['任务能力','当前阶段','触发方式','结果展示','操作'],['<tr><td>会话归档摘要</td><td>'+B('待开发')+'</td><td>聊天结束后</td><td>摘要 / 主题 / 来源</td><td>'+btn('执行详情预览','task-detail','flat')+'</td></tr>','<tr><td>历史记录查询</td><td>'+B('待开发')+'</td><td>用户按需提问</td><td>原文片段 / 时间 / 会话</td><td>'+btn('执行详情预览','task-detail','flat')+'</td></tr>','<tr><td>拍照判题</td><td>'+B('未接入')+'</td><td>后续独立能力</td><td>题目 / 分析版本 / 结果</td><td>'+btn('能力说明','future-capability','flat')+'</td></tr>','<tr><td>提醒与日程</td><td>'+B('未接入')+'</td><td>需持久化调度</td><td>计划 / 触发 / 投递回执</td><td>'+btn('能力说明','future-capability','flat')+'</td></tr>'])+'</section>';}
function configuration(){return head('产品配置','展示配置的作用范围、生效时机和发布回执。',btn('查看变更记录','config-history','','file'))+'<div class="tabs" role="tablist" aria-label="配置分类">'+['设备资料','语音与模型','发布预览'].map(function(t){return '<button role="tab" aria-selected="'+(configTab===t)+'" class="tab '+(configTab===t?'active':'')+'" data-config-tab="'+t+'">'+t+'</button>';}).join('')+'</div>'+(configTab==='设备资料'?settingsForm():configTab==='语音与模型'?'<div class="grid-2">'+panel('当前语音路径',D([['实时语音','千问原生 Realtime'],['服务端','Go'],['设备音频','ESP32-S3'],['语音资料','按云端受保护配置读取'],['密钥','仅云端保存，不在页面展示']])+N('模型与音色的网页编辑尚需服务端字段、允许范围和发布验收。当前只预览配置页面。','info'))+panel('调整方式','<div class="form-field"><label for="voice-role">角色表达</label><select id="voice-role" class="field"><option>温和、自然的家庭陪伴</option><option>简短、清楚的日常助手</option></select><small>角色模板属于拟开发设置。</small></div><div class="divider"></div>'+btn('保存配置草案','save-draft','primary'))+'</div>':panel('发布预览','<div class="timeline"><div class="timeline-item"><h3>编辑配置草案</h3><p class="muted">检查设备范围、版本和当前支持能力。</p></div><div class="timeline-item"><h3>核对变更</h3><p class="muted">名称在新会话生效，设备控制必须收到回读。</p></div><div class="timeline-item"><h3>发布与保存回执</h3><p class="muted">页面区分处理中、已核实和失败，保留回退来源。</p></div></div>'+btn('演示配置发布','publish-demo','primary','upload')));}
function policies(){return head('会话与数据策略','把会话结束、档案保留和模型记忆分开设置。',btn('保存策略示例','save-policy','primary','check'))+'<div class="grid-main"><div class="stack">'+panel('聊天会话','<div class="field-row"><div class="grow"><h3>无有效交互自动结束</h3><small class="muted">从最后一轮交流结束计时，生成和播放中不误结束。</small></div><span class="badge orange">30 分钟</span></div><div class="field-row"><div class="grow"><h3>用户明确结束</h3><small class="muted">立即结束这一段聊天，随后完成归档。</small></div>'+B('优先执行','green')+'</div><div class="field-row"><div class="grow"><h3>按天汇总</h3><small class="muted">一天可以包含多段聊天，零点不强制切分。</small></div><input class="toggle" type="checkbox" checked aria-label="启用每日汇总示例"></div><div class="field-row"><div class="grow"><h3>记录及时保存</h3><small class="muted">不等待会话结束才保存正文。</small></div>'+B('逐轮保存','green')+'</div>',B('规则已确认','green'))+panel('聊天档案','<div class="form-grid"><div class="form-field"><label for="retention">默认保留期限</label><select class="field" id="retention"><option>30天（建议，未定稿）</option><option>7天</option><option>90天</option><option>不留存</option></select><small>此项是拟议政策，不代表当前已有自动删除。</small></div><div class="form-field"><label>原始录音</label><div class="field-row" style="padding:7px 0;border:0">'+B('默认不保存','green')+'</div><small>临时诊断录音需要另行同意和到期规则。</small></div></div>')+'</div><div class="stack">'+panel('设备近期记忆',D([['范围','最近7天 / 最多24轮'],['作用','帮助后续对话接话'],['清除入口','设备记忆 → 清除'],['与档案关系','独立管理，删除需联动']]))+N('“不留存”应同时覆盖正文档案与可恢复记忆；当次聊天仍可使用必要临时上下文。此设置需后端完整实现后开放。','info')+panel('删除与转让','<div class="row-list"><a href="#/memories">'+I('brain')+'<span class="grow">清除设备记忆</span>'+I('chevron')+'</a><button class="btn danger wide" data-action="delete-records">演示删除聊天记录</button><button class="btn flat wide" data-action="transfer-device">演示设备转让</button></div>')+'</div></div>';}
