function render(){var openDialog=document.getElementById('dialog');if(openDialog.open)openDialog.close();current=(location.hash.slice(2).split('?')[0]||'overview');if(!views[current])current='overview';document.title=(U.adminPages.find(function(x){return x[0]===current;})||[])[1]+' · 伴伴控制台';if(current==='login'){app.innerHTML=login();}else{shell(views[current]());}window.scrollTo(0,0);}
